{"claims":[{"claim_text":"Degrowth is a planned and democratic reduction of less necessary forms of production in rich countries to bring economies back into balance with the living world in a safe, just, and equitable way.", "claim_types":["factual_assertion"],"evidence_ids":[2]},{"claim_text":"Jason Hickel defines degrowth as a planned and democratic reduction of less necessary forms of production in rich countries to bring economies back into balance with the living world in a safe, just, and equitable way.", "claim_types":["factual_assertion"],"evidence_ids":[2,3]},{"claim_text":"We are at a critical moment in human history characterized by a rapidly closing window for sufficient climate action, the liberal international order in crisis, a resurgent Left, and an emboldened fascist movement.", "claim_types":["characterization"],"evidence_ids":[4]},{"claim_text":"Degrowth is necessary because there is a rapidly closing window for sufficient climate action and our response must adapt to changing conditions.", "claim_types":["evaluation"],"evidence_ids":[5]},{"claim_text":"Degrowth provides a framework for balancing economy, ecology, and society in a fair, just, and equitable way.", "claim_types":["evaluation"],"evidence_ids":[6]},{"claim_text":"Degrowth is explicitly based on an international ecosocialist revolution of the working-class.", "claim_types":["factual_assertion"],"evidence_ids":[7]},{"claim_text":"YDSA approved a degrowth resolution in 2024, attesting to degrowth’s growing acceptance in DSA and the U.S. Left, especially among younger people.", "claim_types":["factual_assertion"],"evidence_ids":[8]}],"unresolved_references":[]}
